(() => {
  const nuevos = [
    { name: "Rare Reef Afnan", type: "Árabe", gender: "Unisex", image: "data:image/webp;base64," },
    { name: "Armaf Odyssey Pink Pop", type: "Árabe", gender: "Mujer", image: "data:image/webp;base64," },
    { name: "Terre d'Hermès EDT", type: "Diseñador", gender: "Hombre", image: "images/terre-dhermes-edt.webp" },
    { name: "Invictus Elixir Rabanne", type: "Diseñador", gender: "Hombre", image: "images/invictus-elixir-rabanne.webp" },
    { name: "Halloween Man X", type: "Diseñador", gender: "Hombre", image: "images/halloween-man-x.jpg" },
    { name: "Le Beau Le Parfum Jean Paul Gaultier", type: "Diseñador", gender: "Hombre", image: "data:image/webp;base64," }
  ];
  nuevos.forEach(item => {
    if (!products.some(p => p.name === item.name)) {
      const nextId = products.reduce((max,p)=>Math.max(max,p.id),0)+1;
      products.push({ id:nextId, name:item.name, type:item.type, gender:item.gender, prices:priceSets[item.type], image:item.image || null });
    }
  });
  render();
})();
(() => {
  const name = "Summit Elixir Maison Alhambra";
  if (!products.some(p => p.name === name)) {
    products.push({
      id: products.reduce((max, p) => Math.max(max, p.id), 0) + 1,
      name, type: "Árabe", gender: "Unisex",
      prices: priceSets["Árabe"], image: "data:image/webp;base64,"
    });
  }
  render();
})();

